useSeoMeta({title:() => t('Syarat & Ketentuan | Sudut Haramain'),description:() => t('Syarat dan ketentuan penggunaan situs serta konten Sudut Haramain.')})
const sections=[{id:'tentang',title:'1. Tentang Sudut Haramain',paragraphs:['Sudut Haramain adalah media digital yang menyediakan informasi, panduan praktis, cerita, dan konten mengenai Makkah, Madinah, perjalanan, kehidupan lokal, dan topik terkait lainnya. Konten pada situs ini ditujukan sebagai sumber informasi umum dan tidak selalu dimaksudkan sebagai pengganti informasi resmi dari otoritas terkait.']},{id:'penggunaan',title:'2. Penggunaan Situs',paragraphs:['Anda dapat menggunakan Sudut Haramain untuk memperoleh informasi dan menjelajahi konten yang tersedia selama penggunaan tersebut dilakukan secara wajar dan tidak melanggar hukum. Anda tidak diperkenankan menggunakan situs untuk:'],bullets:['mengganggu keamanan atau fungsi situs;','mencoba memperoleh akses tanpa izin terhadap sistem;','mengirimkan konten berbahaya, menyesatkan, atau melanggar hukum;','menggunakan sistem otomatis secara berlebihan sehingga mengganggu layanan;','menyalahgunakan konten atau layanan Sudut Haramain.']},{id:'akurasi',title:'3. Akurasi dan Perubahan Informasi',paragraphs:['Kami berusaha menyajikan informasi yang berguna dan relevan. Namun, kondisi di Makkah dan Madinah dapat berubah sewaktu-waktu. Informasi seperti jadwal, aturan, akses lokasi, transportasi, harga, fasilitas, kebijakan otoritas, prosedur perjalanan, dan kondisi di lapangan dapat berubah setelah sebuah konten diterbitkan. Karena itu, pengguna dianjurkan untuk memeriksa informasi terbaru dari sumber resmi atau pihak terkait.']},{id:'ibadah',title:'4. Informasi Ibadah dan Keagamaan',paragraphs:['Konten mengenai ibadah dan keagamaan disajikan untuk membantu pembaca memahami topik yang dibahas. Untuk persoalan yang membutuhkan penetapan hukum khusus terhadap kondisi pribadi, pengguna dianjurkan merujuk kepada ulama atau pihak yang memiliki kompetensi.']},{id:'kontribusi',title:'5. Kontribusi Pengguna',paragraphs:['Sudut Haramain dapat menyediakan fitur yang memungkinkan pengguna mengirim koreksi informasi, rekomendasi tempat, tips, pengalaman, atau informasi lainnya. Pengiriman kontribusi tidak menjamin bahwa materi tersebut akan diterbitkan. Tim Sudut Haramain dapat meninjau, menggunakan sebagai referensi, menyunting, menindaklanjuti, atau mengabaikan kontribusi sesuai kebutuhan editorial dan operasional. Pengguna bertanggung jawab memastikan materi yang dikirim tidak melanggar hak pihak lain dan tidak mengandung materi yang melanggar hukum.']},{id:'konten',title:'6. Hak atas Konten',paragraphs:['Konten asli, identitas visual, desain, tulisan, ilustrasi, dan materi lain yang dibuat oleh Sudut Haramain dilindungi sesuai ketentuan yang berlaku. Penggunaan untuk kebutuhan pribadi dan berbagi tautan diperbolehkan secara wajar. Penggandaan, penerbitan ulang, penggunaan komersial, atau distribusi substansial tanpa izin tidak diperkenankan kecuali ditentukan lain.']},{id:'pihak-ketiga',title:'7. Tautan dan Layanan Pihak Ketiga',paragraphs:['Sudut Haramain dapat menampilkan tautan menuju situs, aplikasi, peta, layanan, atau sumber informasi milik pihak ketiga. Sudut Haramain tidak mengendalikan isi, kebijakan, ketersediaan, maupun perubahan pada layanan pihak ketiga tersebut.']},{id:'tanggung-jawab',title:'8. Batas Tanggung Jawab',paragraphs:['Pengguna bertanggung jawab atas keputusan yang diambil berdasarkan informasi yang tersedia pada situs. Sepanjang diperbolehkan oleh ketentuan yang berlaku, Sudut Haramain tidak bertanggung jawab atas kerugian yang timbul akibat perubahan kondisi di lapangan, informasi pihak ketiga, gangguan layanan, atau penggunaan informasi di luar konteks.']},{id:'ekosistem',title:'9. Layanan dalam Ekosistem Sudut Haramain',paragraphs:['Beberapa layanan dalam ekosistem Sudut Haramain dapat memiliki situs, proses, harga, kebijakan, atau syarat penggunaan tersendiri. Apabila pengguna menggunakan layanan tersebut, ketentuan khusus yang berlaku pada layanan terkait dapat berlaku selain ketentuan pada situs media Sudut Haramain.']},{id:'perubahan-situs',title:'10. Perubahan Situs dan Layanan',paragraphs:['Sudut Haramain dapat memperbarui, mengubah, menambah, membatasi, atau menghentikan bagian tertentu dari situs apabila diperlukan untuk pengembangan, pemeliharaan, keamanan, atau kebutuhan operasional.']},{id:'perubahan-syarat',title:'11. Perubahan Syarat & Ketentuan',paragraphs:['Syarat & Ketentuan ini dapat diperbarui dari waktu ke waktu. Versi terbaru akan ditampilkan pada halaman ini bersama tanggal pembaruan terakhir.']},{id:'kontak',title:'12. Kontak',paragraphs:['Apabila Anda memiliki pertanyaan mengenai Syarat & Ketentuan ini, silakan menghubungi Sudut Haramain melalui saluran kontak resmi yang tersedia pada situs.']}]

const localizedSections = computed(() => locale.value === 'en' ? legalEnglish.terms : sections)
